diff --git a/components/canvas/canvas-bottom-bar.tsx b/components/canvas/canvas-bottom-bar.tsx
new file mode 100644
index 0000000..746ccfb
--- /dev/null
+++ b/components/canvas/canvas-bottom-bar.tsx
@@ -0,0 +1,58 @@
+'use client';
+
+import { Layers, Zap } from 'lucide-react';
+
+import { Button } from '@/components/ui/button';
+import { cn } from '@/lib/utils';
+import TrackedLink from '@/components/tracked-link';
+import TokenBalance from '@/components/nav/token-balance';
+
+import { CanvasUserMenu } from './canvas-user-menu';
+
+import type { User } from 'next-auth';
+
+interface CanvasBottomBarProps {
+  sessionUser: User;
+  onToggleLayers: () => void;
+  isLayersPanelOpen: boolean;
+}
+
+export function CanvasBottomBar({
+  sessionUser,
+  onToggleLayers,
+  isLayersPanelOpen
+}: CanvasBottomBarProps) {
+  if (!sessionUser) {
+    return null;
+  }
+
+  return (
+    <div
+      className="flex items-center gap-1 rounded-lg bg-background p-1 shadow-lg"
+      data-testid="canvas-bottom-bar"
+    >
+      <Button
+        variant="ghost"
+        size="icon"
+        className={cn(
+          'h-8 w-8',
+          isLayersPanelOpen && 'bg-accent text-accent-foreground'
+        )}
+        onClick={onToggleLayers}
+        data-testid="layers-toggle-button"
+        data-active={isLayersPanelOpen}
+      >
+        <Layers className="h-4 w-4" />
+      </Button>
+      <CanvasUserMenu sessionUser={sessionUser} />
+      <TrackedLink
+        href="/pricing"
+        className="flex items-center gap-1 px-2 py-1 text-sm font-medium hover:bg-accent rounded-md transition-colors"
+        data-testid="canvas-token-link"
+      >
+        <Zap className="h-4 w-4" />
+        <TokenBalance />
+      </TrackedLink>
+    </div>
+  );
+}
diff --git a/components/canvas/canvas-user-menu.tsx b/components/canvas/canvas-user-menu.tsx
new file mode 100644
index 0000000..4e71282
--- /dev/null
+++ b/components/canvas/canvas-user-menu.tsx
@@ -0,0 +1,104 @@
+'use client';
+
+import React from 'react';
+import { useLocale, useTranslations } from 'next-intl';
+import { FaUser } from 'react-icons/fa6';
+import { Ticket } from 'lucide-react';
+
+import { Language } from '@/app/i18n';
+import { Button } from '@/components/ui/button';
+import {
+  DropdownMenu,
+  DropdownMenuContent,
+  DropdownMenuItem,
+  DropdownMenuLabel,
+  DropdownMenuSeparator,
+  DropdownMenuTrigger
+} from '@/components/ui/dropdown-menu';
+import { Dialog, DialogContent, DialogTrigger } from '@/components/ui/dialog';
+import TrackedLink from '@/components/tracked-link';
+import LanguageSelect from '@/components/language-select';
+import { useFeatureFlags } from '@/lib/feature-flags';
+
+import { UserProfileIcon } from '../nav/user-profile-icon';
+import LogoutMenuItem from '../nav/logout-menu-item';
+import TokenBalanceButton from '../nav/token-balance-button';
+import InviteCodeForm from '../nav/invite-code/invite-code-form';
+
+import type { User } from 'next-auth';
+
+export function CanvasUserMenu({ sessionUser }: { sessionUser: User }) {
+  const t = useTranslations();
+  const locale = useLocale();
+  const [open, setOpen] = React.useState(false);
+  const { simpleCanvasMode } = useFeatureFlags();
+
+  if (!sessionUser) {
+    return null;
+  }
+
+  return (
+    <Dialog open={open} onOpenChange={setOpen}>
+      <DropdownMenu modal={false}>
+        <DropdownMenuTrigger asChild>
+          <Button
+            variant="ghost"
+            size="icon"
+            className="h-8 w-8 rounded-full"
+            data-testid="canvas-user-menu-trigger"
+          >
+            <UserProfileIcon
+              userImage={sessionUser.image || ''}
+              userName={sessionUser.name || ''}
+            />
+          </Button>
+        </DropdownMenuTrigger>
+        <DropdownMenuContent
+          className="w-64"
+          side="top"
+          align="start"
+          forceMount
+        >
+          <DropdownMenuLabel className="flex">
+            <TokenBalanceButton className="w-full max-w-none justify-between" />
+          </DropdownMenuLabel>
+          <DropdownMenuSeparator />
+          {!simpleCanvasMode && (
+            <>
+              <DropdownMenuItem className="flex">
+                <TrackedLink
+                  href="/profile"
+                  className="py-2 w-full inline-flex items-center font-bold"
+                >
+                  <FaUser className="w-4 h-4 mr-2" /> {t('My page')}
+                </TrackedLink>
+              </DropdownMenuItem>
+              <DropdownMenuSeparator />
+            </>
+          )}
+          <DialogTrigger asChild>
+            <DropdownMenuItem
+              className="py-3.5 cursor-pointer items-center font-bold"
+              onClick={() => setOpen(true)}
+              data-testid="canvas-use-invite-code-button"
+            >
+              <Ticket className="w-4 h-4 mr-2" />
+              {t('Use invite code')}
+            </DropdownMenuItem>
+          </DialogTrigger>
+          <DropdownMenuSeparator />
+          <DropdownMenuLabel className="py-1 flex justify-between items-center gap-2 font-bold">
+            <span className="whitespace-nowrap">{t('Language')}</span>
+            <LanguageSelect lang={locale as Language} />
+          </DropdownMenuLabel>
+          <DropdownMenuSeparator />
+          <LogoutMenuItem />
+        </DropdownMenuContent>
+      </DropdownMenu>
+
+      <DialogContent>
+        <InviteCodeForm onSuccess={() => setOpen(false)} />
+      </DialogContent>
+    </Dialog>
+  );
+}
